import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    // ([validated by: ../../../specs/hal-engine-tool-input-validation/spec.md#L21])
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    // ([validated by: ../../../specs/hal-engine-tool-input-validation/spec.md#L11])
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('passes valid input with an unlisted extra property through to the executor unchanged', async () => {
    // ([validated by: ../../../specs/hal-engine-tool-input-validation/spec.md#L13])
    const registry = new ToolRegistry();
    let capturedInput: any;
    let executorCalls = 0;
    registry.register(
      {
        name: 'echo',
        description: 'Echoes input',
        inputSchema: {
          type: 'object',
          properties: {msg: {type: 'string'}},
        },
      },
      async input => {
        executorCalls += 1;
        capturedInput = input;
        return 'ok';
      }
    );

    const input = {msg: 'hello', extra: 123};
    await registry.execute('echo', input);
    expect(capturedInput).toEqual(input);
    expect(executorCalls).toBe(1);
  });

  it('throws Unknown tool: <name> for an unregistered name, unchanged, pinned by a test', async () => {
    // ([validated by: ../../../specs/hal-engine-tool-input-validation/spec.md#L14])
    const registry = new ToolRegistry();
    await expect(registry.execute('not_there', {})).rejects.toThrow('Unknown tool: not_there');
  });

  it('asserts a static tool\'s schema is compiled once across ten execute calls', async () => {
    // ([validated by: ../../../specs/hal-engine-tool-input-validation/spec.md#L22])
    const spy = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'static_tool',
        description: 'description',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async () => 'ok'
    );

    expect(spy).toHaveBeenCalledTimes(1);

    for (let i = 0; i < 10; i++) {
      await registry.execute('static_tool', {a: 'test'});
    }

    expect(spy).toHaveBeenCalledTimes(1);
    spy.mockRestore();
  });

  it('asserts a function-valued tool definition whose returned schema differs between calls is validated against the schema current at that call', async () => {
    // ([validated by: ../../../specs/hal-engine-tool-input-validation/spec.md#L23])
    const registry = new ToolRegistry();
    let schemaType = 'string';
    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'description',
        inputSchema: {type: 'object', properties: {a: {type: schemaType}}},
      }),
      async () => 'ok'
    );

    expect((await registry.execute('dynamic_tool', {a: 'test'})).result).not.toContain('validation failed');
    expect((await registry.execute('dynamic_tool', {a: 123})).result).toContain('validation failed');

    schemaType = 'number';
    expect((await registry.execute('dynamic_tool', {a: 123})).result).not.toContain('validation failed');
    expect((await registry.execute('dynamic_tool', {a: 'test'})).result).toContain('validation failed');
  });
});

